        "kind": "communicationReceipt"
      }
    ],
    "subscriptions": [],
    "publications": [],
    "sends": [
      {
        "contract": "task.progress",
        "target": "assistant"
      },
      {
        "contract": "task.result",
        "target": "assistant"
      },
      {
        "contract": "writer.completion",
        "target": "assistant"
      }
    ]
  },
  "baseSkills": [],
  "backgroundTasks": [
